//! AIRSAFE risk engine: Rudnick & Milton (2003) CO2 rebreathed-fraction model, WHO PM2.5 guideline and an
//! illustrative isolation-room pressure target. Port of the original Python engine; tests/risk_parity.rs checks
//! it against 504 cases generated by that Python code. See /api/methodology for the citation behind each constant.
use serde::Serialize;

pub const CO2_OUTDOOR_PPM: f64 = 425.0; // ASHRAE Position Document on Indoor CO2 (2025)
pub const CO2_EXHALED_PPM: f64 = 38000.0; // Rudnick & Milton (2003)
pub const PM25_WHO_24H_UGM3: f64 = 15.0; // WHO Global Air Quality Guidelines (2021)
pub const ISOLATION_TARGET_PA: f64 = -5.0; // illustrative default: replace with the facility specification

pub const CO2_CALIBRATION: [(f64, f64); 6] =
    [(CO2_OUTDOOR_PPM, 0.0), (620.0, 20.0), (800.0, 40.0), (1000.0, 60.0), (1600.0, 80.0), (2500.0, 100.0)];

#[derive(Debug, Clone, Serialize)]
pub struct Driver {
    pub factor: String,
    pub value: String,
    pub contribution: f64,
    pub source: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct RiskResult {
    pub score: f64,
    pub rebreathed_fraction_pct: f64,
    pub co2_component: f64,
    pub pm25_penalty: f64,
    pub pressure_penalty: Option<f64>,
    pub drivers: Vec<Driver>,
}

fn round_to(x: f64, digits: i32) -> f64 {
    let m = 10f64.powi(digits);
    (x * m).round() / m
}

pub fn rebreathed_fraction(co2: f64) -> f64 {
    ((co2 - CO2_OUTDOOR_PPM) / (CO2_EXHALED_PPM - CO2_OUTDOOR_PPM)).max(0.0)
}

fn co2_index(co2: f64) -> f64 {
    let pts = CO2_CALIBRATION;
    if co2 <= pts[0].0 {
        return 0.0;
    }
    for i in 0..pts.len() - 1 {
        let (x0, y0) = pts[i];
        let (x1, y1) = pts[i + 1];
        if x0 <= co2 && co2 <= x1 {
            return y0 + ((co2 - x0) / (x1 - x0)) * (y1 - y0);
        }
    }
    100.0
}

fn pm25_penalty(pm25: f64) -> f64 {
    if pm25 <= PM25_WHO_24H_UGM3 {
        return 0.0;
    }
    (((pm25 - PM25_WHO_24H_UGM3) / 35.0) * 15.0).min(15.0)
}

fn pressure_penalty(dp: f64) -> f64 {
    if dp <= ISOLATION_TARGET_PA {
        return 0.0;
    }
    let mag = ISOLATION_TARGET_PA.abs();
    (((dp - ISOLATION_TARGET_PA) / mag) * 15.0).min(15.0)
}

pub fn compute_score(co2: f64, pm25: f64, dp: Option<f64>) -> RiskResult {
    let f = rebreathed_fraction(co2);
    let co2c = co2_index(co2);
    let pm_pen = pm25_penalty(pm25);
    let p_pen = dp.map(pressure_penalty);

    let raw = co2c * 0.85 + pm_pen + p_pen.unwrap_or(0.0);
    let score = raw.clamp(0.0, 100.0);

    let mut drivers = vec![Driver {
        factor: "CO2 rebreathed fraction".into(),
        value: format!("{:.0} ppm ({:.2}% rebreathed air)", co2, f * 100.0),
        contribution: round_to(co2c * 0.85, 1),
        source: "Rudnick & Milton (2003), Indoor Air 13(3):237-245".into(),
    }];
    if pm_pen > 0.0 {
        drivers.push(Driver {
            factor: "PM2.5 above WHO guideline".into(),
            value: format!("{:.0} ug/m3 (guideline: {:.0})", pm25, PM25_WHO_24H_UGM3),
            contribution: round_to(pm_pen, 1),
            source: "WHO Global Air Quality Guidelines (2021)".into(),
        });
    }
    if let (Some(pen), Some(dp_val)) = (p_pen, dp) {
        if pen > 0.0 {
            drivers.push(Driver {
                factor: "Differential pressure below target".into(),
                value: format!("{:.1} Pa (target: {:.1} Pa)", dp_val, ISOLATION_TARGET_PA),
                contribution: round_to(pen, 1),
                source: "Illustrative facility target -- not a specific cited regulatory value".into(),
            });
        }
    }

    RiskResult {
        score: round_to(score, 1),
        rebreathed_fraction_pct: round_to(f * 100.0, 2),
        co2_component: round_to(co2c, 1),
        pm25_penalty: round_to(pm_pen, 1),
        pressure_penalty: p_pen.map(|p| round_to(p, 1)),
        drivers,
    }
}

pub fn status_label(score: f64) -> &'static str {
    if score < 20.0 {
        "Safe"
    } else if score < 40.0 {
        "Low"
    } else if score < 60.0 {
        "Moderate"
    } else if score < 80.0 {
        "High"
    } else {
        "Critical"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn calibration_anchors() {
        assert_eq!(compute_score(425.0, 0.0, None).score, 0.0);
        assert_eq!(compute_score(800.0, 0.0, None).score, 34.0); // 40 * 0.85
        assert_eq!(compute_score(2500.0, 0.0, None).score, 85.0); // 100 * 0.85
        assert_eq!(status_label(19.9), "Safe");
        assert_eq!(status_label(80.0), "Critical");
    }

    #[test]
    fn pressure_only_counts_above_target() {
        assert!(compute_score(600.0, 5.0, Some(-6.0)).pressure_penalty == Some(0.0));
        assert!(compute_score(600.0, 5.0, Some(0.0)).pressure_penalty.unwrap() > 0.0);
        assert_eq!(compute_score(600.0, 5.0, None).pressure_penalty, None);
    }
}
